package com.ianblk.zianmanager;
import com.google.gson.JsonObject;
import net.minecraft.server.level.ServerPlayer;
import com.ianblk.zianmanager.core.EncounterLedger.*;
import java.util.*;
public final class ZoneRefreshSmoke {
 public static void verify(ManagerRuntime runtime,ServerPlayer player)throws Exception{var old=runtime.store().data().zones().get("smoke_room");var before=runtime.encounter(old.id());var server=player.getServer();server.getPlayerList().op(player.getGameProfile());try{runtime.request(player,"zone",old.id());var fields=new JsonObject();fields.addProperty("id",old.id());fields.addProperty("name","Cripta renovada");fields.addProperty("team",String.join(",",old.team()));fields.addProperty("waves",old.waves());fields.addProperty("pauseSeconds",old.pauseSeconds());fields.addProperty("respawnSeconds",20);fields.addProperty("enabled",true);fields.addProperty("completionLoot",old.completionLoot());var sf=ManagerRuntime.class.getDeclaredField("sessions");sf.setAccessible(true);var session=((Map<?,?>)sf.get(runtime)).get(player.getUUID());var token=session.getClass().getDeclaredMethod("token");token.setAccessible(true);runtime.action(player,new ManagerNetwork.Action((UUID)token.invoke(session),"save",fields.toString()));if(!runtime.store().data().zones().get(old.id()).name().equals("Cripta renovada") || runtime.encounter(old.id()).readyAt()!=before.readyAt()+10000)throw new IllegalStateException("Saved name or cooldown did not apply to current wait");int result=server.getCommands().getDispatcher().execute("zianmanager applyzone smoke_room",player.createCommandSourceStack());if(result!=1 || !runtime.store().data().zones().get(old.id()).enabled() || runtime.encounter(old.id()).phase()!=Phase.CANCELLED || runtime.encounter(old.id()).readyAt()!=0)throw new IllegalStateException("Apply command did not reset encounter while keeping zone enabled");}finally{server.getPlayerList().deop(player.getGameProfile());}ZianManager.LOGGER.info("Zian Manager zone refresh smoke passed: renamed public label, live cooldown change, apply command and enabled reset");}
}
